"""Case020 read-only display projection. Stdlib; no Torch, GPU or new benchmark."""
from html import escape
import csv,importlib.util,math,statistics
from common import read,sha,require
C20='cases/020-optic-on-demand-decode'
TITLES={'ko':'임베딩을 작게 보관하면 실행도 빨라질까?','en':'Does Smaller Embedding Storage Also Run Faster?'}
SECTIONS=('overview','memory','calls','width','reuse','method','reproduce','references')
SOURCE_COPIES={
 **{'case020-'+kind+'-'+lang+'.md.txt':C20+'/'+name+('.ko.md' if lang=='ko' else '.md') for kind,name in [('guide','README'),('report','REPORT'),('reproduce','REPRODUCE')] for lang in ('ko','en')},
 'case020-notice.md.txt':C20+'/NOTICE.md','case020-source-map.md.txt':C20+'/SOURCE_MAP.md','case020-reuse-map.md.txt':C20+'/REUSE_MAP.md',
 'case020-facts.json.txt':C20+'/summary/facts.json','case020-direct.csv.txt':C20+'/summary/representative_direct_block.csv',
 'case020-paired.csv.txt':C20+'/summary/P4_paired_H.csv','case020-width.csv.txt':C20+'/summary/width_storage.csv',
 'case020-lifecycle.csv.txt':C20+'/summary/lifecycle_block.csv','case020-analysis.py.txt':C20+'/publication/analyze.py',
 'case020-checks.py.txt':C20+'/publication/run_checks.py','case020-requirements.txt':C20+'/publication/requirements-cpu.txt',
}
FIGURES={'assets/case020-'+name+'.svg':C20+'/figures/'+name+'.svg' for name in ['01_memory','02_direct_calls','03_width_storage','04_session_worker']}
def rows(case,name):
 with (case/'summary'/name).open(newline='') as f:return list(csv.DictReader(f))
def close(a,b,label):require(math.isclose(float(a),float(b),rel_tol=1e-11,abs_tol=1e-9),label)
def projection(case):
 """Cross-check displayed aggregates from saved block tables, not saved PASS flags."""
 f=read(case/'summary/facts.json');h=[r for r in rows(case,'all_P4_clock_statistics.csv') if r['pass']=='H'];life=rows(case,'lifecycle_block.csv');direct=rows(case,'representative_direct_summary.csv');width=rows(case,'width_storage.csv');lsummary=rows(case,'lifecycle_summary.csv')
 require(len(h)==96 and len(life)==27 and len(direct)==9 and len(width)==3,'Case020 display denominators')
 require(f['P2_final_cell_blocks']==90 and f['P2_diagnostic_cell_blocks']==90 and f['P4_timing_workers']==30 and f['P4_method_blocks']==96 and f['P4_lifecycle_workers']==27,'Case020 recorded phases')
 ix={(int(r['Z']),r['input'],int(r['block']),r['method']):r for r in h};pairs=[]
 for key,c in ix.items():
  if key[-1]!='C':continue
  b=ix[*key[:-1],'B'];ratio=float(c['median_us'])/float(b['median_us']);pairs.append((*key[:-1],ratio))
 require(len(pairs)==f['P4_C_B_block_comparisons']==30 and sum(p[-1]<1 for p in pairs)==f['P4_C_faster_blocks']==0,'Case020 C/B direction')
 for r in f['ratios']:
  pp=[p[-1] for p in pairs if p[:2]==(r['Z'],r['input'])];require(len(pp)==r['blocks'],'Case020 paired blocks');close(statistics.median(pp),r['median_of_block_C_B_ratios'],'Case020 paired median')
 for r in direct:
  rr=[x for x in h if all(x[k]==r[k] for k in ['Z','M','U','method'])];require(len(rr)==int(r['blocks']),'Case020 direct blocks')
  for key in ['median_us','p95_us']:
   vals=[float(x[key]) for x in rr]
   for suffix,fn in [('block_median',statistics.median),('block_min',min),('block_max',max)]:close(r[key+'_'+suffix],fn(vals),'Case020 direct aggregate')
 for r in lsummary:
  rr=[x for x in life if (x['N'],x['method'])==(r['N'],r['method'])];require(len(rr)==int(r['blocks'])==3,'Case020 lifecycle blocks')
  for key in ['session_wall_seconds','worker_wall_seconds']:close(r[key+'_median'],statistics.median(float(x[key]) for x in rr),'Case020 lifecycle median')
 lm={(r['N'],r['method']):r for r in lsummary}
 for key in ['session_wall_seconds','worker_wall_seconds']:
  close(f['N4096_A_reduction_ratio_of_method_medians'][key],1-float(lm['4096','A'][key+'_median'])/float(lm['4096','B'][key+'_median']),'Case020 lifecycle reduction')
 for r in width:
  z=int(r['Z']);g=z//4;theory=32768*g+2*256*z+2*16*256*z+2*16*256+8*g;require(int(r['groups'])==g and int(r['observed_unique_module_storage_bytes'])==theory==int(r['theoretical_storage_bytes']),'Case020 storage accounting')
 m={x['method']:x for x in f['memory']['observations'] if x['block']==0};require(set(m)==set('ABC'),'Case020 isolated memory');close(f['memory']['A_to_B_allocated_peak_reduction'],1-m['B']['total_allocated_peak_bytes']/m['A']['total_allocated_peak_bytes'],'Case020 allocated reduction')
 return {'facts':f,'memory':[m[k] for k in 'ABC'],'direct':direct,'width':width,'lifecycle':lsummary,'direct_blocks':rows(case,'representative_direct_block.csv'),'lifecycle_blocks':life}
def load_case020(root):
 case=root/C20
 if not (case/'README.md').exists():return None
 spec=importlib.util.spec_from_file_location('case020_site_identity',case/'publication/verify.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v);identity=v.verify(case)
 result=projection(case);result['public_identity']={'manifest_sha256':sha(case/'PUBLIC_MANIFEST.json'),'preserved_case_files':identity['preserved_case_files'],'preserved_external_files':identity['preserved_external_files']}
 sources=[*SOURCE_COPIES.values(),*FIGURES.values(),C20+'/PUBLIC_MANIFEST.json',C20+'/summary/all_P4_clock_statistics.csv',C20+'/summary/representative_direct_summary.csv',C20+'/summary/lifecycle_summary.csv']
 result['display_source_files']={p:sha(root/p) for p in sources};return result

def link(url,label):return '<a href="'+escape(url,quote=True)+'">'+escape(label)+'</a>'
def table(head,body,label="Recorded comparison"):return '<div class="scroll" tabindex="0" role="region" aria-label="'+escape(label,quote=True)+'"><table><thead><tr>'+''.join('<th scope="col">'+escape(str(v))+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in row)+'</tr>' for row in body)+'</tbody></table></div>'
def figure(name,alt,caption):return '<figure><img loading="lazy" src="../assets/case020-'+name+'.svg" alt="'+escape(alt,quote=True)+'"><figcaption>'+escape(caption)+'</figcaption></figure>'
def home_case020(data,lang):
 t=lambda k,e:k if lang=='ko' else e
 return '<section class="panel case020-entry" id="case020-entry"><h2>Case020 · '+escape(TITLES[lang])+'</h2><p>'+t('같은 압축 임베딩을 전부 미리 계산할지, 요청할 때 계산할지 비교했습니다. 공식 OPTIC 코드와 합성 표를 사용했습니다.','Compared precomputing an embedding table with reconstructing requested rows, using official OPTIC code and synthetic tables.')+'</p><p>'+t('PyTorch 할당 최대값은 약304→81MiB로 줄었지만, 중복 제거 C가 B보다 빠른 block은0/30이었습니다. 실제1024·4096회 재사용 세션에서는 A가 세 block 모두 빨랐습니다.','PyTorch allocated peak fell from about 304 to 81 MiB, while C beat B in 0/30 process blocks. Actual1024/4096-call reuse sessions favored A in all three blocks.')+'</p><div class="actions">'+link('case020.html#overview',t('쉽게 읽기','Plain explanation'))+' · '+link('case020.html#calls',t('직접 호출 비용','Direct call costs'))+' · '+link('case020.html#reproduce',t('CPU 검산','CPU checks'))+'</div></section>'
def render_case020(data,lang):
 ko=lang=='ko';t=lambda k,e:k if ko else e;f=data['facts'];labels=dict(zip(SECTIONS,[t('질문과 세 방법','Question and methods'),t('메모리','Memory'),t('한 번의 호출','Individual calls'),t('중간 벡터 폭','Intermediate width'),t('오래 재사용할 때','Repeated reuse'),t('방법과 이력','Method and history'),t('CPU 검산','CPU checks'),t('출처와 기여','Sources and contributions')]))
 out='<div class="case020-layout"><nav class="case020-toc" aria-label="'+t('이 문서에서','On this page')+'">'+''.join(link('#'+key,labels[key]) for key in SECTIONS)+'</nav><article class="case020">'
 def section(key,body):return '<section class="panel" id="'+key+'"><h2>'+escape(labels[key])+'</h2>'+body+'</section>'
 methods=[['A',t('전체를 미리 계산','Precompute all'),t('같은 압축 표현의 전체 표를 만든 뒤 번호로 조회','Build the whole table from the same compressed representation, then look up rows')],['B',t('요청한 항목만 계산','Compute requested rows'),t('공식 decoder로 M개 요청 행 복원','Official decoder reconstructs M requested rows')],['C',t('중복은 한 번 계산한 뒤 순서 복구','Compute distinct rows and restore order'),t('매번 중복 찾기 → U개 복원 → M개로 복구','Find duplicates each call → decode U rows → return M rows')]]
 intro='<h1>'+escape(TITLES[lang])+'</h1><p class="c20-lead">'+t('토큰은 모델이 처리하는 글의 작은 단위이고, 임베딩은 토큰을 나타내는 숫자 벡터입니다. 각 층에서 쓰는 추가 임베딩을 전부 미리 계산해 둘지, 필요한 번호를 받을 때만 계산할지 비교했습니다.','A token is a small unit of text; an embedding is a vector of numbers representing it. We compared calculating every extra layer embedding ahead of time with calculating only the requested rows.')+'</p><p>'+t('실제 LLM 대신 공식 OPTIC 복원 코드와 합성 표를 RTX5080에서 비교했습니다. A도 같은 압축 표현에서 계산한 표이므로 원래 미압축 임베딩과 같다는 뜻은 아닙니다.','The RTX5080 study used official OPTIC reconstruction code and synthetic tables instead of loading an LLM. A is reconstructed from the same representation, not the original uncompressed embedding table.')+'</p>'+table(['',t('쉬운 이름','Plain name'),t('하는 일','What it does')],methods,'A B C')
 intro+='<ul class="c20-results"><li>'+t('메모리: PyTorch 할당 최대값 약304→81 MiB, 약73% 감소. GPU 전체 VRAM 감소율은 아닙니다.','Memory: PyTorch allocated peak about 304→81 MiB, about 73% less. This is not device-wide VRAM reduction.')+'</li><li>'+t('호출: P4의7조건·30개 process block에서 C가 B보다 빠른 block은0/30이었습니다.','Calls: C was faster than B in 0/30 process blocks across 7 P4 conditions.')+'</li><li>'+t('재사용: 실제 N1024·4096 세션에서는 A가 B보다 세 block 모두 빨랐습니다.','Reuse: actual N1024/4096-call sessions favored A over B in all three blocks.')+'</li></ul>';out+=section('overview',intro)
 mem=table([t('방법','Method'),t('상주 tensor MiB','Resident tensors MiB'),t('할당 최대 MiB','Allocated peak MiB'),t('재사용 확보 포함 MiB','Reserved peak MiB')],[[r['method'],f"{r['resident_bytes']/2**20:.4f}",f"{r['total_allocated_peak_bytes']/2**20:.3f}",f"{r['total_reserved_peak_bytes']/2**20:.0f}"] for r in data['memory']],'P2 isolated memory')
 mem+='<p>'+t('LARGE/Z32/M2048/U512의 원 P2 독립 process 측정입니다. 상주 tensor는 호출 사이에도 GPU에 남는 숫자 배열입니다. 할당 최대값은 계산 중 PyTorch가 기록한 최대값이며, reserved는 재사용하려고 확보한 공간까지 포함합니다. 출력은16MiB입니다.','These are original isolated P2 processes for LARGE/Z32/M2048/U512. Resident tensors stay on the GPU between calls; allocated peak is PyTorch’s recorded maximum during calculation; reserved includes memory held for reuse. Output is 16 MiB.')+'</p><p>'+t('C의 할당 최대값은 B보다 작지만 reserved는 더 큽니다. 상주 module의 약489배 차이와 전체 장치 VRAM은 구분합니다.','C has a smaller allocated peak than B but a higher reserved peak. The roughly 489-fold module-payload ratio is not a total-VRAM ratio.')+'</p>'+figure('01_memory','Resident tensor payload and allocated peak',t('검은 점은 세 독립 block이며 같은 값은 겹칩니다. allocated에는 공통32 MiB baseline이 포함됩니다.','Black points are three independent blocks; identical values overlap. Allocated includes the common32 MiB baseline.'));out+=section('memory',mem)
 direct=[]
 for r in data['direct']:direct.append([f"{r['Z']}/{r['M']}/{r['U']}",r['method'],r['blocks'],f"{float(r['median_us_block_median']):.2f} [{float(r['median_us_block_min']):.2f}–{float(r['median_us_block_max']):.2f}]",f"{float(r['p95_us_block_median']):.2f}"])
 calls='<p>'+t('같은 process에 A와 compact module을 함께 두고 호출 순서를 바꾼 H 주 지표입니다. 호출과 GPU 완료 대기를 host 시계로 쟀습니다. 각 block의120회 통계를 먼저 계산했습니다. 아래는 block 중앙값들의 중앙값과 범위이며 p95도 block 통계의 중앙값입니다.','Primary H keeps A and a compact module in the same process and alternates call order. Host timing includes waiting for GPU completion. Each block measures120 calls; the table reports medians/ranges of block medians and the median of block p95s.')+'</p>'+table(['Z/M/U',t('방법','Method'),'blocks',t('중앙값 µs [block 범위]','Median µs [block range]'),'p95 µs'],direct,'Direct H latency')
 calls+=table(['Z','M/U','blocks','C/B',t('C가 빠른 block','C faster blocks')],[[r['Z'],'1/1' if r['input']=='m1' else '2048/2048' if r['input']=='unique2048' else '2048/512',r['blocks'],f"{r['median_of_block_C_B_ratios']:.3f}",f"{r['C_faster_blocks']}/{r['blocks']}"] for r in f['ratios']],'Paired C B ratios')
 calls+='<p>'+t('C/B는 각 block의 짝 비율을 먼저 만든 뒤 중앙값을 낸 값입니다. 위 절대시간 중앙값끼리 나눈 값과 다를 수 있습니다. 내부120회나30개 block을 독립 모델·사용자 과제로 세지 않습니다. 느린 원점도 남겼습니다.','C/B takes paired ratios within each block before summarizing them. It can differ from dividing marginal medians above. Inner calls and 30 blocks are not independent models/user tasks. Slow points remain.')+'</p>'+figure('02_direct_calls','Direct call medians, p95 and paired ratios',t('위의 채운 점은 block 중앙값, 짧은 tick은 p95입니다. 이어진 선은 신뢰구간이 아닙니다. 아래는 각 block의 C/B입니다.','Top filled points are block medians and ticks are p95, not confidence bars. Bottom points are paired C/B block ratios.'));out+=section('calls',calls)
 width=table(['Z','groups',t('실제 module bytes','Observed module bytes'),t('실제 MiB','Observed MiB'),t('dense/module','Dense/module')],[[r['Z'],r['groups'],r['observed_unique_module_storage_bytes'],f"{float(r['module_MiB']):.4f}",f"{float(r['dense_over_observed_module']):.2f}"] for r in data['width']])
 width+='<p>'+t('Z는 복원 계산의 중간 벡터 폭입니다. 실제 buffer inventory의 dtype·shape·고유 storage를 합했고 group_offsets도 포함했습니다. Z와 함께 groups·사전·연산량도 변합니다. Z32의489배를 Z644에 적용하지 않습니다. Z644는 E4B의 폭만 대응하며 전체 모델이나 품질 재현이 아닙니다.','Z is the intermediate-vector width. Observed storage sums dtype/shape-checked unique buffer storage, including group_offsets. Groups, codebooks and work change with Z. Z32’s489-fold ratio does not apply to Z644. Z644 matches only E4B’s width, not its full model or quality.')+'</p>'+figure('03_width_storage','Compact storage and C B latency by width',t('점은 각 block입니다. 반복 입력의 Z644에서도 C/B 중앙비는1.142로 C가 느렸습니다.','Points are process blocks. Even repeated-ID Z644 gave a1.142 median C/B ratio, with slower C.'));out+=section('width',width)
 reuse=table(['N',t('방법','Method'),t('세션 중앙값 s','Session median s'),t('전체 process 중앙값 s','Whole-worker median s')],[[r['N'],r['method'],f"{float(r['session_wall_seconds_median']):.6f}",f"{float(r['worker_wall_seconds_median']):.6f}"] for r in data['lifecycle']],'Real repeated call sessions')
 reuse+='<p>'+t('세션은 자료 읽기·준비·실제 N회 호출·정리까지입니다. 전체 worker는 Python 시작·공통 CUDA 초기화·종료까지 포함합니다. warm-up 없이 첫 호출도 N에 넣었고, 첫 호출은 loop의 일부이므로 두 번 더하지 않습니다.','Session includes reading, setup, N actual calls and cleanup. Whole-worker wall also includes Python startup, common CUDA initialization and exit. No warm-up: the first call counts toward N and is already part of the loop.')+'</p><p>'+t('N128의 세션은 A/B 우열이 섞였고 전체 worker는 B가3/3 빨랐지만 중앙값 차이는 약17ms였습니다. N4096에서 A는 방법별 세 block 중앙값 기준으로 B보다 세션53.0%, 전체 worker23.8% 낮았습니다. C는 모든 N의 세션 중앙값이 B보다 높지만 N4096 한 block은 C&lt;B였습니다. 정확한 운영 교차점을 보간하지 않습니다.','N128 session ordering was mixed; whole workers favored B in 3/3 blocks with only about 17 ms median difference. At N4096, comparing each method’s three-block medians, A was 53.0% cheaper in session wall and 23.8% in whole-worker wall. C had a higher session median at every N, but one N4096 block had C&lt;B. No exact operational crossover is interpolated.')+'</p>'+figure('04_session_worker','Session and whole worker wall by actual call count',t('세 점은 실제 block 원점이며 가운데는 중앙값, 막대는 최소–최대입니다. 신뢰구간이나 단일 호출 p95가 아닙니다.','Three points are actual block origins; centers are medians and bars are min–max, not confidence intervals or per-call p95.'));out+=section('reuse',reuse)
 method='<p>'+t('원 P2 최종90 cell-block과 순서 이탈이 있던 첫90개 diagnostic을 분리 보존했습니다. 과거 host C승리5/30, event mean4/30, 공통0/30도 그대로입니다. P4는 timing30 worker/96 method-block와 lifecycle27 worker, preflight3+smoke1+memory3을 합해 신규64 worker입니다.','Final P2’s90 cell-blocks and the earlier90 diagnostic records with an order deviation remain separate. Historical C wins remain host5/30, event-mean4/30, common0/30. P4 has30 timing workers/96 method-blocks,27 lifecycle workers and 3 preflight+1 smoke+3 memory workers:64 total.')+'</p><p>'+t('H는 동기 host 호출, D는 같은 호출의 host/event 이중 타이머, E는 K16 stream 경과시간/16입니다. D host에는 event 기록과 wait가 들어가고 E는 순수 kernel 합이 아닙니다. S는 중복 없는 한 조건에서 정렬 후 M행을 복원한 별도 대조입니다.','H is synchronized host timing; D pairs host/events on one call; E is K16 stream elapsed/16. D’s host includes event records/wait; E is not pure kernel sum. S sorts and decodes M rows in one duplicate-free control.')+'</p><p>'+t('새 replay의32 MiB 잔류 할당은 cuBLAS handle workspace stack으로 확인했습니다. 과거 allocation의 stack을 소급해 읽은 것은 아닙니다. 실제 LLM·학습 품질·TTFT/TPOT·서버 동시성·전기료는 측정하지 않았습니다.','The new replay identifies retained32 MiB as cuBLAS handle workspace from allocation stacks; it does not recover old allocation stacks. LLM quality, TTFT/TPOT, concurrency and energy costs remain unmeasured.')+'</p>';out+=section('method',method)
 command='python3.12 -m venv /tmp/case020-cpu\n/tmp/case020-cpu/bin/python -m pip install -r '+C20+'/publication/requirements-cpu.txt\nOPENBLAS_NUM_THREADS=1 /tmp/case020-cpu/bin/python -I -B '+C20+'/publication/run_checks.py --mode full --tests --output /tmp/case020-full-new'
 # Korean/English strings below intentionally describe commands, not runtime internals.
 rep='<p>'+t('GitHub에서 저장소를 받은 뒤, 모델·GPU 없이 저장 기록을 검산합니다. Python3.12.14/NumPy2.3.5/Matplotlib3.10.8의 새 CPU 환경에서 확인했습니다.','After cloning the repository, check saved records without a model/GPU. Tested in a new CPU environment with Python3.12.14, NumPy2.3.5 and Matplotlib3.10.8.')+'</p><pre><code>'+escape(command)+'</code></pre><p>'+t('quick은 bytes·timing·작은 참조를, full은 보존한 원 P2/P4 감사·수치·그림 재생성을 추가 검사합니다. 새 GPU 추론 재현으로 부르지 않습니다. 큰 raw·NPZ는 사이트에서 자동 다운로드하지 않고 GitHub 원자료로 연결합니다.','Quick checks bytes, timing and a small reference; full adds preserved P2/P4 numerical audits and figure regeneration. Neither is new GPU inference. Large raw/NPZ files stay in GitHub and are not automatically downloaded by this site.')+'</p><div class="actions">'+link('../sources/case020-reproduce-'+lang+'.md.txt',t('환경과 quick/full 명령','Environment and quick/full commands'))+' · '+link('../sources/case020-direct.csv.txt',t('모든 직접 block','All direct blocks'))+' · '+link('../sources/case020-lifecycle.csv.txt',t('실제 세션 원점','Actual session origins'))+'</div>';out+=section('reproduce',rep)
 references='<p>'+t('직접 만든 부분은 fixture·비교 wrapper·계측·독립 NumPy 검산·표시 도구입니다. OPTIC codec와 Torch GEMM/allocator를 재사용했고 Codex가 구현·분석·문서화를 보조했습니다. 원 실행 source와 새 표시 source는 구분합니다.','Our work covers fixtures, wrappers, measurement, independent NumPy checks and display tools. OPTIC’s codec and Torch GEMM/allocator are reused; Codex assisted implementation, analysis and documentation. Execution source and new display source remain distinct.')+'</p><div class="actions">'+link('https://arxiv.org/abs/2610.31309','OPTIC v1')+' · '+link('https://github.com/VILA-Lab/optic/tree/344c712aeb6620e39eb78930fb922447f0e123f3','Pinned OPTIC')+' · '+link('../sources/case020-source-map.md.txt','Source map')+' · '+link('../sources/case020-analysis.py.txt',t('CPU 계산 코드','CPU calculation code'))+' · '+link('../sources/case020-report-'+lang+'.md.txt',t('상세 보고서','Detailed report'))+' · '+link('https://github.com/Munsik-Kim/inference-lab/tree/main/'+C20,t('GitHub 원자료','GitHub evidence'))+'</div>';out+=section('references',references)
 return out+'<noscript><p>'+t('JavaScript 없이도 위 표·그림·원자료 링크를 읽을 수 있습니다.','Tables, figures and source links remain readable without JavaScript.')+'</p></noscript></article></div>'
